#!/usr/bin/env python3 import sys from pathlib import Path def find_downloads_dir(): home = Path.home() candidates = [ home / "storage" / "downloads", # Termux storage home / "storage" / "Download", home / "Downloads", Path("/sdcard/Download"), Path("/sdcard/Downloads"), Path("/storage/emulated/0/Download"), Path("/storage/emulated/0/Downloads"), ] for d in candidates: if d.exists() and d.is_dir(): return d # Fallback: create and use ~/Downloads fallback = home / "Downloads" fallback.mkdir(parents=True, exist_ok=True) return fallback def main(): # Optional content passed as command-line arguments; otherwise default text content = "This is txt.txt content.\n" if len(sys.argv) > 1: content = " ".join(sys.argv[1:]) downloads_dir = find_downloads_dir() file_path = downloads_dir / "txt.txt" try: with file_path.open("w", encoding="utf-8") as f: f.write(content) print(f"Saved: {file_path}") except Exception as e: print(f"Failed to save {file_path}: {e}", file=sys.stderr) sys.exit(1) if __name__ == "__main__": main()
